query:
SELECT id, title, articleType, status, qualityScore, publicPath, optimizationTaskId FROM geo_articles WHERE projectId = 1 ORDER BY id LIMIT 10;
SELECT id, articleId, optimizationTaskId, qualityScore, publishUrl, publishStatus, needRetest, publishChannel FROM geo_publish_records WHERE projectId = 1 ORDER BY id DESC LIMIT 5;
SELECT id, taskName, status, needRetest, published_url FROM optimization_tasks WHERE projectId = 1 AND id IN (120010, 120011, 120012) ORDER BY id;
SELECT (SELECT COUNT(*) FROM geo_reports WHERE projectId = 1) AS report_count, (SELECT COUNT(*) FROM content_templates WHERE projectId = 1) AS template_count, (SELECT COUNT(*) FROM ai_response_analyses WHERE projectId = 1 AND manuallyReviewed = 1) AS manually_reviewed_analysis_count, (SELECT COUNT(*) FROM customer_questions WHERE projectId = 1 AND source = 'manual') AS specified_question_count;

